function outputFiles = plot_distance_figures(configPath)
%PLOT_DISTANCE_FIGURES Plot configured trajectory traces and distance histograms.
% The configuration is generated by scripts/python/configure_pipeline.py.

projectRoot = fileparts(fileparts(fileparts(mfilename('fullpath'))));
if nargin < 1 || isempty(configPath)
    configPath = fullfile(projectRoot, 'config', 'pipeline_config.json');
end
if ~isfile(configPath)
    error('Configuration file not found: %s', configPath);
end

cfg = jsondecode(fileread(configPath));
if ~isfield(cfg, 'figures') || isempty(cfg.figures)
    error('No figures are configured in %s.', configPath);
end

outputDir = char(cfg.output_dir);
if isfield(cfg, 'path_base_dir') && ~isempty(cfg.path_base_dir)
    pathBaseDir = char(cfg.path_base_dir);
else
    pathBaseDir = pwd;
end
if ~isAbsolutePath(outputDir)
    outputDir = fullfile(pathBaseDir, outputDir);
end
if ~isfolder(outputDir)
    error('Results folder not found: %s. Run the VMD scripts first.', outputDir);
end

figureDir = fullfile(outputDir, 'figures');
if ~isfolder(figureDir)
    mkdir(figureDir);
end

metadataDir = outputDir;
referenceFile = fullfile(outputDir, 'reference_distances.csv');
signatureAxes = collectSignatureAxes(cfg, metadataDir, referenceFile);
outputFiles = strings(numel(cfg.figures), 1);

for figureIndex = 1:numel(cfg.figures)
    figureConfig = cfg.figures(figureIndex);
    panelCount = numel(figureConfig.panels);
    if panelCount == 0
        error('Figure %d has no panels.', figureIndex);
    end
    if panelCount > figureConfig.rows * figureConfig.columns
        error('Figure %d has more panels than its configured layout allows.', figureIndex);
    end

    fig = figure('Color', 'w', 'Position', [100 100 1100 700]);
    layout = tiledlayout(fig, figureConfig.rows, figureConfig.columns, ...
        'TileSpacing', 'compact', 'Padding', 'compact');
    sgtitle(layout, string(figureConfig.title), 'Interpreter', 'none');

    for panelIndex = 1:panelCount
        panel = figureConfig.panels(panelIndex);
        systemId = string(panel.system_id);
        signatureId = string(panel.signature_id);
        systemIndex = find(strcmp({cfg.systems.id}, char(systemId)), 1);
        signatureIndex = find(strcmp({cfg.signatures.id}, char(signatureId)), 1);
        if isempty(systemIndex) || isempty(signatureIndex)
            error('Figure %d panel %d refers to an unknown system or signature.', ...
                figureIndex, panelIndex);
        end
        systemConfig = cfg.systems(systemIndex);
        signatureConfig = cfg.signatures(signatureIndex);
        axisSpec = signatureAxes(char(signatureId));

        metadataPath = fullfile(metadataDir, ...
            sprintf('%s_%s_all_frame_metadata.csv', char(systemId), char(signatureId)));
        if ~isfile(metadataPath)
            error('Missing VMD output file: %s', metadataPath);
        end
        data = readtable(metadataPath);
        requiredColumns = {'replica', 'vmd_frame', 'distance_angstrom'};
        if ~all(ismember(requiredColumns, data.Properties.VariableNames))
            error('Metadata file is missing required columns: %s', metadataPath);
        end
        if isempty(data)
            error('Metadata file contains no distance rows: %s', metadataPath);
        end

        ax = nexttile(layout, panelIndex);
        hold(ax, 'on');
        refs = table();
        if panel.show_references && isfile(referenceFile)
            refs = selectReferences(referenceFile, systemId, signatureId);
        end

        if strcmpi(char(panel.kind), 'trajectory')
            replicaLabels = unique(string(data.replica), 'stable');
            replicaColors = trajectoryColorMap(numel(replicaLabels));
            for replicaIndex = 1:numel(replicaLabels)
                replica = replicaLabels(replicaIndex);
                replicaData = data(string(data.replica) == replica, :);
                replicaData = sortrows(replicaData, 'vmd_frame');
                frameIndex = double(replicaData.vmd_frame);
                intervalNs = double(systemConfig.frame_interval_ns);
                if intervalNs > 0
                    x = frameIndex .* (intervalNs / 1000);
                    xLabel = 'Time (μs)';
                else
                    x = frameIndex;
                    xLabel = 'Loaded VMD frame';
                end
                plot(ax, x, double(replicaData.distance_angstrom), ...
                    'LineWidth', 1.1, 'Color', replicaColors(replicaIndex, :), ...
                    'DisplayName', "replica " + replica);
            end
            for referenceIndex = 1:height(refs)
                referenceName = string(refs.reference_name(referenceIndex));
                yline(ax, double(refs.distance_angstrom(referenceIndex)), '-', ...
                    'Color', referenceLineColor(referenceName), 'LineWidth', 1.3, ...
                    'DisplayName', referenceName);
            end
            ylim(ax, axisSpec.limits);
            yticks(ax, axisSpec.ticks);
            xlabel(ax, xLabel);
            ylabel(ax, 'Distance (Å)');
            title(ax, string(systemConfig.display_name) + " | " + ...
                string(signatureConfig.label) + " | distances", ...
                'Interpreter', 'none');
            legend(ax, 'Location', 'best', 'Interpreter', 'none');
        elseif strcmpi(char(panel.kind), 'histogram')
            distanceValues = double(data.distance_angstrom);
            [frameCounts, binEdges] = histcounts( ...
                distanceValues, double(cfg.histogram_bins));
            binCenters = binEdges(1:end-1) + diff(binEdges) ./ 2;

            intervalNs = double(systemConfig.frame_interval_ns);
            if intervalNs > 0
                xValues = frameCounts .* (intervalNs / 1000);
                xLabel = 'Time observed (μs)';
            else
                xValues = frameCounts;
                xLabel = 'Frame count';
            end
            barh(ax, binCenters, xValues, ...
                'FaceColor', [0 0 0], 'EdgeColor', [0 0 0], ...
                'HandleVisibility', 'off');

            referenceDistances = double(refs.distance_angstrom);
            for referenceIndex = 1:height(refs)
                referenceName = string(refs.reference_name(referenceIndex));
                yline(ax, referenceDistances(referenceIndex), '-', ...
                    'Color', referenceLineColor(referenceName), 'LineWidth', 1.3, ...
                    'DisplayName', referenceName);
            end

            ylim(ax, axisSpec.limits);
            yticks(ax, axisSpec.ticks);
            if any(xValues > 0)
                xUpper = max(1, ceil(max(xValues)));
                xlim(ax, [0 xUpper]);
                if intervalNs > 0
                    xticks(ax, 0:0.5:xUpper);
                end
            end
            xlabel(ax, xLabel);
            ylabel(ax, 'Distance (Å)');
            title(ax, string(systemConfig.display_name) + " | " + ...
                string(signatureConfig.label) + " | distribution", ...
                'Interpreter', 'none');
            if ~isempty(refs)
                legend(ax, 'Location', 'best', 'Interpreter', 'none');
            end
        else
            error('Unknown panel kind "%s". Choose trajectory or histogram.', panel.kind);
        end

        grid(ax, 'on');
        box(ax, 'on');
        set(ax, 'FontSize', 10, 'LineWidth', 1);
        hold(ax, 'off');
    end

    baseName = sprintf('figure_%02d_%s', figureIndex, ...
        safeFilePart(char(figureConfig.title)));
    figPath = fullfile(figureDir, [baseName '.fig']);
    pngPath = fullfile(figureDir, [baseName '.png']);
    savefig(fig, figPath);
    exportgraphics(fig, pngPath, 'Resolution', 300);
    outputFiles(figureIndex) = string(pngPath);
end

fprintf('Saved %d figure(s) in %s\n', numel(outputFiles), figureDir);
end


function signatureAxes = collectSignatureAxes(cfg, metadataDir, referenceFile)
ranges = containers.Map('KeyType', 'char', 'ValueType', 'any');

for figureIndex = 1:numel(cfg.figures)
    panels = cfg.figures(figureIndex).panels;
    for panelIndex = 1:numel(panels)
        panel = panels(panelIndex);
        systemId = string(panel.system_id);
        signatureId = string(panel.signature_id);
        metadataPath = fullfile(metadataDir, ...
            sprintf('%s_%s_all_frame_metadata.csv', char(systemId), char(signatureId)));
        if ~isfile(metadataPath)
            error('Missing VMD output file: %s', metadataPath);
        end
        data = readtable(metadataPath);
        if ~ismember('distance_angstrom', data.Properties.VariableNames) || isempty(data)
            error('Distance metadata is missing values: %s', metadataPath);
        end

        axisValues = double(data.distance_angstrom(:));
        if panel.show_references && isfile(referenceFile)
            refs = selectReferences(referenceFile, systemId, signatureId);
            axisValues = [axisValues; double(refs.distance_angstrom(:))];
        end
        axisValues = axisValues(isfinite(axisValues));
        if isempty(axisValues)
            error('No finite distance values are available for %s.', signatureId);
        end

        key = char(signatureId);
        panelRange = [min(axisValues), max(axisValues)];
        if isKey(ranges, key)
            currentRange = ranges(key);
            ranges(key) = [min(currentRange(1), panelRange(1)), ...
                max(currentRange(2), panelRange(2))];
        else
            ranges(key) = panelRange;
        end
    end
end

signatureAxes = containers.Map('KeyType', 'char', 'ValueType', 'any');
keysForSignatures = ranges.keys;
for index = 1:numel(keysForSignatures)
    key = keysForSignatures{index};
    [limits, ticks] = niceDistanceAxis(ranges(key));
    signatureAxes(key) = struct('limits', limits, 'ticks', ticks);
end
end


function [limits, ticks] = niceDistanceAxis(valueRange)
minimumValue = valueRange(1);
maximumValue = valueRange(2);
if minimumValue == maximumValue
    padding = max(1, abs(minimumValue) * 0.1);
    minimumValue = minimumValue - padding;
    maximumValue = maximumValue + padding;
end

rawStep = (maximumValue - minimumValue) / 7;
scale = 10 ^ floor(log10(rawStep));
normalizedStep = rawStep / scale;
if normalizedStep <= 1
    tickStep = scale;
elseif normalizedStep <= 2
    tickStep = 2 * scale;
elseif normalizedStep <= 5
    tickStep = 5 * scale;
else
    tickStep = 10 * scale;
end

lowerLimit = floor(minimumValue / tickStep) * tickStep;
upperLimit = ceil(maximumValue / tickStep) * tickStep;
if lowerLimit == upperLimit
    lowerLimit = lowerLimit - tickStep;
    upperLimit = upperLimit + tickStep;
end
tickCount = round((upperLimit - lowerLimit) / tickStep);
ticks = lowerLimit + (0:tickCount) * tickStep;
limits = [lowerLimit upperLimit];
end


function refs = selectReferences(referenceFile, systemId, signatureId)
refs = table();
if ~isfile(referenceFile)
    return;
end
% Specify the CSV schema explicitly. MATLAB's automatic header detection can
% mistake quoted reference data for variable names on some installations.
opts = delimitedTextImportOptions('NumVariables', 5);
opts.Delimiter = ',';
opts.VariableNamesLine = 1;
opts.DataLines = [2 Inf];
opts.VariableNames = {'system_name', 'reference_name', 'signature_name', ...
    'reference_file', 'distance_angstrom'};
opts.VariableTypes = {'string', 'string', 'string', 'string', 'double'};
allReferences = readtable(referenceFile, opts);
required = {'system_name', 'reference_name', 'signature_name', 'distance_angstrom'};
if ~all(ismember(required, allReferences.Properties.VariableNames))
    error('Reference file is missing required columns: %s', referenceFile);
end
keep = string(allReferences.system_name) == systemId & ...
    string(allReferences.signature_name) == signatureId;
refs = allReferences(keep, :);
end


function colors = trajectoryColorMap(count)
% Keep trajectory colors separate from the red and blue reference lines.
warmCount = max(1, ceil(0.75 * count));
if warmCount == 1
    warmHues = 0.08;
else
    warmHues = linspace(0.08, 0.52, warmCount);
end
coolCount = count - warmCount;
if coolCount > 0
    coolHues = linspace(0.78, 0.91, coolCount);
else
    coolHues = [];
end
hues = [warmHues(:); coolHues(:)];
colors = hsv2rgb([hues, 0.78 * ones(count, 1), 0.82 * ones(count, 1)]);
end


function color = referenceLineColor(referenceName)
label = lower(strtrim(char(referenceName)));
if contains(label, 'inactive')
    color = [1 0 0];
elseif contains(label, 'active')
    color = [0 0 1];
else
    color = [0.25 0.25 0.25];
end
end


function result = isAbsolutePath(pathText)
if ispc
    result = ~isempty(regexp(pathText, '^[A-Za-z]:[\\/]', 'once')) || ...
        startsWith(pathText, '\\');
else
    result = startsWith(pathText, filesep);
end
end


function result = safeFilePart(text)
result = regexprep(text, '[^A-Za-z0-9_-]+', '_');
result = regexprep(result, '^_+|_+$', '');
if isempty(result)
    result = 'analysis';
end
end
